create or replace function public.manufacturer_certification_status() returns table(program_id uuid,company_id uuid,company_name text,learner_count bigint,certified_learners bigint,minimum_required int,is_certified boolean) language plpgsql stable security definer set search_path='' as $f$ declare mid uuid;begin select active_manufacturer_id into mid from public.profiles where id=auth.uid();if mid is null or not private.has_manufacturer_role(mid,array['owner','admin','content_manager']::public.manufacturer_role[]) then raise exception 'Permission denied';end if;return query
select p.id,a.company_id,c.name,count(cm.user_id),count(cm.user_id)filter(where not exists(select 1 from public.certification_requirements r where r.program_id=p.id and not(case when r.content_type='quiz' then exists(select 1 from public.quiz_attempts qa join public.quizzes q on q.id=qa.quiz_id where qa.company_id=a.company_id and qa.user_id=cm.user_id and qa.quiz_id=r.content_id and qa.status='completed' and qa.score>=q.passing_score) else (select count(*) from public.course_block_progress cp where cp.company_id=a.company_id and cp.user_id=cm.user_id and cp.course_id=r.content_id)>=(select count(*) from public.course_blocks b join public.course_modules m on m.id=b.module_id where m.course_id=r.content_id) and (select count(*) from public.course_blocks b join public.course_modules m on m.id=b.module_id where m.course_id=r.content_id)>0 end))),p.minimum_certified_learners,(count(cm.user_id)filter(where not exists(select 1 from public.certification_requirements r where r.program_id=p.id and not(case when r.content_type='quiz' then exists(select 1 from public.quiz_attempts qa join public.quizzes q on q.id=qa.quiz_id where qa.company_id=a.company_id and qa.user_id=cm.user_id and qa.quiz_id=r.content_id and qa.status='completed' and qa.score>=q.passing_score) else (select count(*) from public.course_block_progress cp where cp.company_id=a.company_id and cp.user_id=cm.user_id and cp.course_id=r.content_id)>=(select count(*) from public.course_blocks b join public.course_modules m on m.id=b.module_id where m.course_id=r.content_id) and (select count(*) from public.course_blocks b join public.course_modules m on m.id=b.module_id where m.course_id=r.content_id)>0 end)))>=p.minimum_certified_learners)
from public.company_certification_assignments a join public.certification_programs p on p.id=a.program_id join public.companies c on c.id=a.company_id left join public.company_members cm on cm.company_id=a.company_id and cm.status='active' where p.manufacturer_id=mid group by p.id,a.company_id,c.name;end $f$;
revoke all on function public.manufacturer_certification_status() from public,anon;grant execute on function public.manufacturer_certification_status() to authenticated;
